package de.ibikus.appa.hephaestus.restservice.catalog.adapter.out.persistence;

import de.ibikus.appa.hephaestus.restservice.catalog.domain.Category;
import de.ibikus.appa.hephaestus.restservice.catalog.domain.CategoryId;
import de.ibikus.appa.hephaestus.restservice.catalog.domain.Item;
import de.ibikus.appa.hephaestus.restservice.catalog.domain.ItemId;
import de.ibikus.appa.hephaestus.restservice.catalog.domain.Money;
import java.util.UUID;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;

/** Domain <-> JPA entity mapping, generated by MapStruct. */
@Mapper(imports = Money.class)
interface PersistenceMapper {

    @Mapping(target = "version", ignore = true)
    CategoryJpaEntity toNewEntity(Category category);

    Category toDomain(CategoryJpaEntity entity);

    @Mapping(target = "version", ignore = true)
    @Mapping(target = "priceAmount", source = "price.amount")
    @Mapping(target = "priceCurrency", source = "price.currency")
    ItemJpaEntity toNewEntity(Item item);

    @Mapping(target = "price", expression = "java(new Money(entity.getPriceAmount(), entity.getPriceCurrency()))")
    // MapStruct treats Item.replace(NewItem) as a fluent setter; it is behaviour, not a property
    @Mapping(target = "replace", ignore = true)
    Item toDomain(ItemJpaEntity entity);

    default UUID map(CategoryId id) {
        return id == null ? null : id.value();
    }

    default CategoryId toCategoryId(UUID id) {
        return id == null ? null : new CategoryId(id);
    }

    default UUID map(ItemId id) {
        return id == null ? null : id.value();
    }

    default ItemId toItemId(UUID id) {
        return id == null ? null : new ItemId(id);
    }
}
